B=Path(__file__).resolve().parents[1]/'results/pose-baseline';protocol=json.loads((B/'frozen-protocol.json').read_text());training=[json.loads((B/(c['id']+'.json')).read_text()) for c in protocol['training']];X=np.array([r['features'] for r in training]);y=[r['expected'] for r in training]
